"use client";

import {
  useBuilderStore,
  useBuilderContext,
} from "@buildnbuzz/form-builder-react";
import { FieldIcon } from "./field-icon";
import { cn } from "@/lib/utils";

/**
 * Rich drag overlay item that provides visual feedback during DnD.
 * Matches legacy DragOverlayItem but integrates with the new registry pattern.
 */
export function DragOverlayItem({
  activeId,
  activeData,
}: {
  activeId: string;
  activeData: Record<string, unknown>;
}) {
  const { registry } = useBuilderContext();
  const node = useBuilderStore((s) => s.nodes[activeId]);

  const data = activeData as Record<string, unknown>;
  const isFromSidebar = data?.from === "sidebar";
  const type = (isFromSidebar ? data?.type : node?.field?.type) as
    | string
    | undefined;
  const entry = type ? registry[type] : null;

  const label =
    entry?.sidebar?.label ?? (typeof type === "string" ? type : "Field");

  // Get field name for existing fields
  let fieldName: string | undefined;
  if (!isFromSidebar && node && "name" in node.field) {
    fieldName = node.field.name;
  }

  return (
    <div
      className={cn(
        "bg-card/95 backdrop-blur-md border-2 shadow-2xl rounded-xl p-3 min-w-[20rem] cursor-grabbing",
        "animate-in fade-in-0 zoom-in-95 duration-150",
        isFromSidebar
          ? "border-primary/50 shadow-primary/10"
          : "border-border shadow-black/10",
      )}
    >
      <div className="flex items-center gap-3">
        {/* Icon container */}
        <div
          className={cn(
            "p-2.5 rounded-lg flex items-center justify-center",
            isFromSidebar
              ? "bg-primary/15 text-primary"
              : "bg-muted text-foreground",
          )}
        >
          {type ? (
            <FieldIcon type={type} size={20} />
          ) : (
            <FieldIcon type="text" size={20} />
          )}
        </div>

        {/* Text content */}
        <div className="flex-1 min-w-0 text-left">
          <div className="text-sm font-semibold text-foreground truncate">
            {isFromSidebar ? `New ${label}` : (fieldName ?? label)}
          </div>
          <div className="text-xs text-muted-foreground flex items-center gap-1.5 whitespace-nowrap">
            <FieldIcon
              type={isFromSidebar ? "plus" : "move"}
              size={12}
            />
            <div className="flex items-center gap-1">
              {isFromSidebar ? (
                <>
                  Adding new, press
                  <kbd className="inline-flex items-center rounded border border-border bg-muted px-1.5 py-0.5 text-[10px] font-medium text-foreground/80">
                    Esc
                  </kbd>
                  to cancel
                </>
              ) : (
                "Moving field"
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { DynamicCodeBlock } from "fumadocs-ui/components/dynamic-codeblock";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { IconPlaceholder } from "@/components/icon-placeholder";
import {
  generateComponentCode,
  nodesToFields,
  toSafeFileName,
} from "@buildnbuzz/form-builder-core";
import {
  useBuilderStore,
  downloadTextFile,
} from "@buildnbuzz/form-builder-react";

const starterCommand =
  "npx shadcn@latest add https://form.buildnbuzz.com/r/all.json";

export function ExportSheet() {
  const [open, setOpen] = React.useState(false);

  const nodes = useBuilderStore((state) => state.nodes);
  const rootIds = useBuilderStore((state) => state.rootIds);
  const formName = useBuilderStore((state) => state.formName);
  const outputConfig = useBuilderStore((state) => state.outputConfig);

  const componentCode = React.useMemo(() => {
    if (!open) return "";
    return generateComponentCode(nodes, rootIds, formName, outputConfig);
  }, [open, nodes, rootIds, formName, outputConfig]);

  const schemaJson = React.useMemo(() => {
    if (!open) return "";
    const fields = nodesToFields(nodes, rootIds);
    const schema = {
      title: formName || "BuzzForm Export",
      fields,
    };
    return JSON.stringify(schema, null, 2);
  }, [open, nodes, rootIds, formName]);

  const downloadSchema = React.useCallback(() => {
    if (!schemaJson) return;
    const fileName = `${toSafeFileName(formName)}.json`;
    downloadTextFile(schemaJson, fileName, "application/json");
    toast.success("BuzzForm schema exported");
  }, [schemaJson, formName]);

  const downloadCode = React.useCallback(() => {
    if (!componentCode) return;
    const fileName = `${toSafeFileName(formName)}.tsx`;
    downloadTextFile(componentCode, fileName, "text/plain;charset=utf-8");
    toast.success("Component code exported");
  }, [componentCode, formName]);

  const copyToClipboard = React.useCallback((text: string, label: string) => {
    navigator.clipboard.writeText(text);
    toast.success(`${label} copied to clipboard`);
  }, []);

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger
        render={
          <Button variant="outline" className="gap-2">
            <IconPlaceholder
              hugeicons="FileExportIcon"
              lucide="FileDown"
              tabler="IconFileExport"
              phosphor="FileArrowDown"
              remixicon="RiFileDownloadLine"
              size={16}
              strokeWidth={2}
            />
            Export
          </Button>
        }
      />

      <SheetContent
        side="right"
        className="w-full p-0 gap-0 data-[side=right]:w-[min(96vw,1120px)] data-[side=right]:sm:max-w-280"
      >
        <SheetHeader className="border-b pr-12">
          <SheetTitle>Export Form</SheetTitle>
          <SheetDescription>
            Export production-ready TSX or portable BuzzForm schema JSON.
          </SheetDescription>
        </SheetHeader>

        <Tabs
          defaultValue="tsx"
          className="flex h-full min-h-0 flex-1 flex-col p-4"
        >
          <TabsList variant="line" className="w-full">
            <TabsTrigger value="tsx" className="gap-1.5">
              <IconPlaceholder
                hugeicons="SourceCodeIcon"
                lucide="Code"
                tabler="IconCode"
                phosphor="Code"
                remixicon="RiCodeLine"
                size={16}
                strokeWidth={2}
              />
              App Code
              <Badge variant="outline">.tsx</Badge>
            </TabsTrigger>
            <TabsTrigger value="schema" className="gap-1.5">
              <IconPlaceholder
                hugeicons="File02Icon"
                lucide="File"
                tabler="IconFile"
                phosphor="File"
                remixicon="RiFileCodeLine"
                size={16}
                strokeWidth={2}
              />
              BuzzForm Schema
              <Badge variant="outline">.json</Badge>
            </TabsTrigger>
          </TabsList>

          <TabsContent value="tsx" className="min-h-0 flex-1 overflow-hidden">
            <ScrollArea className="h-full px-4 py-2">
              <div className="space-y-3 p-1">
                <div className="rounded-lg border bg-muted/30 p-3">
                  <div className="mb-3 flex items-center gap-2 text-sm font-medium">
                    <IconPlaceholder
                      hugeicons="SourceCodeIcon"
                      lucide="Code"
                      tabler="IconCode"
                      phosphor="Code"
                      remixicon="RiCodeLine"
                      size={16}
                      strokeWidth={1.8}
                      className="text-muted-foreground"
                    />
                    Required setup
                  </div>
                  <div className="[&_figure]:my-0!">
                    <DynamicCodeBlock lang="bash" code={starterCommand} />
                  </div>
                  <div className="mt-3 flex flex-wrap items-center gap-2">
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={downloadCode}
                    >
                      <IconPlaceholder
                        hugeicons="Download01Icon"
                        lucide="Download"
                        tabler="IconDownload"
                        phosphor="DownloadSimple"
                        remixicon="RiDownload2Line"
                        size={16}
                        strokeWidth={2}
                      />
                      Download TSX File
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => copyToClipboard(componentCode, "App code")}
                    >
                      <IconPlaceholder
                        hugeicons="Copy01Icon"
                        lucide="Copy"
                        tabler="IconCopy"
                        phosphor="Copy"
                        remixicon="RiFileCopyLine"
                        size={16}
                        strokeWidth={2}
                      />
                      Copy Code
                    </Button>
                  </div>
                </div>

                <div className="[&_figure]:my-0!">
                  <DynamicCodeBlock lang="tsx" code={componentCode} />
                </div>
              </div>
            </ScrollArea>
          </TabsContent>

          <TabsContent
            value="schema"
            className="min-h-0 flex-1 overflow-hidden"
          >
            <ScrollArea className="h-full px-4 py-2">
              <div className="space-y-3 p-1">
                <div className="rounded-lg border bg-muted/30 p-3">
                  <div className="mb-3 flex items-center gap-2 text-sm font-medium">
                    <IconPlaceholder
                      hugeicons="File02Icon"
                      lucide="File"
                      tabler="IconFile"
                      phosphor="File"
                      remixicon="RiFileCodeLine"
                      size={16}
                      strokeWidth={1.8}
                      className="text-muted-foreground"
                    />
                    BuzzForm schema
                  </div>
                  <p className="text-sm text-muted-foreground">
                    Pure schema JSON for copy/paste import and runtime form
                    generation.
                  </p>
                  <div className="mt-2 flex flex-wrap items-center gap-2">
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={downloadSchema}
                    >
                      <IconPlaceholder
                        hugeicons="Download01Icon"
                        lucide="Download"
                        tabler="IconDownload"
                        phosphor="DownloadSimple"
                        remixicon="RiDownload2Line"
                        size={16}
                        strokeWidth={2}
                      />
                      Download BuzzForm Schema
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => copyToClipboard(schemaJson, "Schema JSON")}
                    >
                      <IconPlaceholder
                        hugeicons="Copy01Icon"
                        lucide="Copy"
                        tabler="IconCopy"
                        phosphor="Copy"
                        remixicon="RiFileCopyLine"
                        size={16}
                        strokeWidth={2}
                      />
                      Copy JSON
                    </Button>
                  </div>
                </div>

                <div className="[&_figure]:my-0!">
                  <DynamicCodeBlock lang="json" code={schemaJson} />
                </div>
              </div>
            </ScrollArea>
          </TabsContent>
        </Tabs>
      </SheetContent>
    </Sheet>
  );
}

"use client";

import React from "react";
import { useDataField } from "@buildnbuzz/form-react";
import type { ExpressionGroup } from "@buildnbuzz/form-builder-core";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { Button } from "@/components/ui/button";
import { IconPlaceholder } from "@/components/icon-placeholder";
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field";
import { cn } from "@/lib/utils";
import { ExpressionBuilder } from "./index";

type ExpressionValue = boolean | undefined | ExpressionGroup;

function isExpressionGroup(value: unknown): value is ExpressionGroup {
  return (
    typeof value === "object" &&
    value !== null &&
    (value as ExpressionGroup).type === "group"
  );
}

/**
 * Dual-mode property widget for boolean/expression fields.
 *
 * - Static mode: renders a Checkbox or Switch (per `field.type`) with a ⚡ button.
 * - Expression mode: renders an "Expression active" badge with Edit and Clear buttons.
 *
 * Toggling ⚡ opens the ExpressionBuilder dialog. Saving stores an ExpressionGroup.
 * Clearing reverts to `false` (static boolean).
 */
export function ExpressionCheckbox() {
  const {
    field,
    fieldApi,
    isDisabled,
    isReadOnly,
    isRequired,
    label,
    description,
    errors,
    isInvalid,
    descriptionId,
    errorId,
    ariaDescribedBy,
    handleBlur,
    handleChange,
  } = useDataField();

  const value = fieldApi.state.value as ExpressionValue;
  const disabled = isDisabled || isReadOnly;
  const isExpression = isExpressionGroup(value);
  const boolValue = isExpression ? false : ((value as boolean | undefined) ?? false);
  const fieldType = (field as { type?: string }).type;

  const ui = (
    field as {
      ui?: {
        alignment?: "start" | "end" | "between";
        autoFocus?: boolean;
        className?: string;
        expressionMode?: "default" | "only" | "none";
      };
    }
  ).ui;
  const alignment = ui?.alignment ?? "between";
  const expressionMode = ui?.expressionMode ?? "default";

  const handleSave = (group: ExpressionGroup) => handleChange(group);
  const handleClear = () => handleChange(expressionMode === "only" ? undefined : false);

  // 1. The active expression node (replaces the input)
  const activeControlNode = (
    <div
      className={cn(
        "flex shrink-0 items-center justify-center border border-amber-500/50 bg-amber-500/10 text-amber-600 dark:text-amber-500",
        fieldType === "switch" ? "h-5 w-9 rounded-full" : "h-4 w-4 mt-0.5 rounded-sm"
      )}
    >
      <IconPlaceholder
        lucide="Zap"
        hugeicons="Lightning"
        tabler="IconBolt"
        phosphor="Lightning"
        remixicon="RiFlashlightLine"
        size={fieldType === "switch" ? 12 : 10}
        className="fill-amber-500/20"
      />
    </div>
  );

  const expressionBar = isExpression ? (
    <div className="mt-2 flex items-center justify-between rounded-md border border-amber-500/30 bg-amber-500/5 px-2 py-1 shadow-sm">
      <div className="flex items-center gap-1.5 text-xs font-medium text-amber-600 dark:text-amber-500">
        <IconPlaceholder
          lucide="Zap"
          hugeicons="Lightning"
          tabler="IconBolt"
          phosphor="Lightning"
          remixicon="RiFlashlightLine"
          size={14}
          className="fill-amber-500/20"
        />
        Dynamic Expression
      </div>
      <div className="flex items-center gap-0.5">
        <ExpressionBuilder
          initialValue={value as ExpressionGroup}
          onSave={handleSave}
          trigger={
            <Button
              variant="ghost"
              size="icon-sm"
              className="h-6 w-6 text-amber-600/70 hover:bg-amber-500/10 hover:text-amber-600 dark:text-amber-500/70 dark:hover:text-amber-500"
            >
              <IconPlaceholder
                lucide="Pencil"
                hugeicons="PencilEdit01Icon"
                tabler="IconPencil"
                phosphor="PencilSimple"
                remixicon="RiPencilLine"
                size={12}
              />
            </Button>
          }
        />
        <Button
          variant="ghost"
          size="icon-sm"
          className="h-6 w-6 text-amber-600/70 hover:bg-destructive/10 hover:text-destructive dark:text-amber-500/70 dark:hover:text-destructive"
          onClick={handleClear}
          disabled={disabled}
        >
          <IconPlaceholder
            lucide="X"
            hugeicons="Cancel01Icon"
            tabler="IconX"
            phosphor="X"
            remixicon="RiCloseLine"
            size={12}
          />
        </Button>
      </div>
    </div>
  ) : expressionMode === "only" && !isExpression ? (
    <div className="mt-2">
      <ExpressionBuilder
        initialValue={undefined}
        onSave={handleSave}
        trigger={
          <Button
            variant="outline"
            size="sm"
            className="h-7 w-full gap-1.5 border-dashed text-xs text-muted-foreground hover:border-amber-500/50 hover:bg-amber-500/5 hover:text-amber-500"
          >
            <IconPlaceholder
              lucide="Zap"
              hugeicons="Lightning"
              tabler="IconBolt"
              phosphor="Lightning"
              remixicon="RiFlashlightLine"
              size={14}
            />
            Set Expression
          </Button>
        }
      />
    </div>
  ) : null;

  // 2. The static control node
  const switchNode = (
    <Switch
      id={fieldApi.name}
      checked={boolValue}
      onCheckedChange={(checked) => {
        handleChange(checked);
        handleBlur();
      }}
      disabled={disabled}
      aria-invalid={isInvalid}
      aria-describedby={ariaDescribedBy}
      aria-readonly={isReadOnly}
      autoFocus={ui?.autoFocus}
      size="sm"
    />
  );

  const checkboxNode = (
    <Checkbox
      id={fieldApi.name}
      checked={boolValue}
      onCheckedChange={(checked) => {
        handleChange(!!checked);
        handleBlur();
      }}
      disabled={disabled}
      aria-invalid={isInvalid}
      aria-describedby={ariaDescribedBy}
      aria-readonly={isReadOnly}
      autoFocus={ui?.autoFocus}
    />
  );

  const emptyControlNode = (
    <div
      className={cn(
        "flex shrink-0 items-center justify-center text-muted-foreground/30",
        fieldType === "switch" ? "h-5 w-9" : "h-4 w-4 mt-0.5"
      )}
    >
      <IconPlaceholder
        lucide="Zap"
        hugeicons="Lightning"
        tabler="IconBolt"
        phosphor="Lightning"
        remixicon="RiFlashlightLine"
        size={fieldType === "switch" ? 12 : 10}
      />
    </div>
  );

  const controlNode = isExpression
    ? activeControlNode
    : expressionMode === "only"
      ? emptyControlNode
      : fieldType === "switch"
        ? switchNode
        : checkboxNode;

  // 3. The content element (label, description, error, expression bar)
  const isSwitchBetween = fieldType === "switch" && alignment === "between";
  const contentElement = (
    <FieldContent className={isSwitchBetween ? "flex-1" : undefined}>
      {label && (
        <FieldLabel
          htmlFor={fieldApi.name}
          className={cn(
            "cursor-pointer m-0 font-normal",
            isSwitchBetween ? "flex-none gap-1 items-baseline" : "inline"
          )}
        >
          {isSwitchBetween && isRequired && <span className="text-destructive">*</span>}
          {label}
          {!isSwitchBetween && isRequired && <span className="text-destructive">&nbsp;*</span>}
        </FieldLabel>
      )}
      {description && !isInvalid && (
        <FieldDescription id={descriptionId}>{description}</FieldDescription>
      )}
      {isInvalid && <FieldError id={errorId} errors={errors} />}
      {expressionBar}
    </FieldContent>
  );

  // 4. Assemble the layout
  return (
    <FieldGroup data-field={fieldApi.name} className={cn("group/expr", ui?.className)}>
      <div className="flex items-start gap-2 w-full">
        <Field
          orientation="horizontal"
          className={cn("flex-1", isSwitchBetween && "w-full justify-between")}
          data-invalid={isInvalid}
          data-disabled={disabled}
        >
          {fieldType === "switch" ? (
            alignment === "start" ? (
              <>
                {controlNode}
                {contentElement}
              </>
            ) : (
              <>
                {contentElement}
                {controlNode}
              </>
            )
          ) : (
            // Default Checkbox layout
            <>
              {controlNode}
              {contentElement}
            </>
          )}
        </Field>

        {/* Lightning bolt trigger (only visible when static mode and default mode) */}
        {!isExpression && expressionMode === "default" && (
          <ExpressionBuilder
            initialValue={undefined}
            onSave={handleSave}
            trigger={
              <Button
                variant="ghost"
                size="icon-sm"
                className="h-6 w-6 shrink-0 opacity-0 transition-all hover:bg-amber-500/10 hover:text-amber-500 focus-visible:opacity-100 group-hover/expr:opacity-100 dark:text-muted-foreground"
                disabled={disabled}
              >
                <IconPlaceholder
                  lucide="Zap"
                  hugeicons="Lightning"
                  tabler="IconBolt"
                  phosphor="Lightning"
                  remixicon="RiFlashlightLine"
                  size={14}
                />
              </Button>
            }
          />
        )}
      </div>
    </FieldGroup>
  );
}

"use client";

import React from "react";
import type { StoreApi } from "zustand";
import { cn } from "@/lib/utils";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Empty,
  EmptyHeader,
  EmptyTitle,
  EmptyDescription,
  EmptyMedia,
} from "@/components/ui/empty";
import {
  SortableContext,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { type ExpressionGroup } from "@buildnbuzz/form-builder-core";
import { type ExpressionStoreState } from "@buildnbuzz/form-builder-react";
import { Card, CardContent, CardFooter } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { IconPlaceholder } from "@/components/icon-placeholder";
import { SortableItem } from "./sortable-item";
import { ExpressionRuleItem } from "./expression-rule";

interface ExpressionGroupItemProps {
  group: ExpressionGroup;
  parentId?: string;
  isRoot?: boolean;
  store: StoreApi<ExpressionStoreState>;
}

export function ExpressionGroupItem({
  group,
  parentId,
  isRoot = false,
  store,
}: ExpressionGroupItemProps) {
  const [isOpen, setIsOpen] = React.useState(true);
  const {
    updateGroupOperator,
    removeNode,
    addRule,
    addGroup,
    duplicateGroup,
  } = store.getState();

  const headerContent = (
    <div
      className={cn(
        "flex flex-col sm:flex-row items-start sm:items-center gap-2 p-1.5 transition-all relative",
        isRoot
          ? "rounded-xl"
          : cn(
              "bg-muted/50 cursor-pointer group/header hover:bg-muted/80 rounded-t-xl",
              isOpen ? "rounded-b-none" : "rounded-b-xl"
            )
      )}
    >
      {!isRoot && (
        <div className="flex items-center justify-center w-6 h-6 shrink-0 text-muted-foreground mr-1">
          {isOpen ? (
            <IconPlaceholder
              lucide="ChevronDown"
              hugeicons="ArrowDown01Icon"
              tabler="IconChevronDown"
              phosphor="CaretDown"
              remixicon="RiArrowDownSLine"
              size={18}
            />
          ) : (
            <IconPlaceholder
              lucide="ChevronRight"
              hugeicons="ArrowRight01Icon"
              tabler="IconChevronRight"
              phosphor="CaretRight"
              remixicon="RiArrowRightSLine"
              size={18}
            />
          )}
        </div>
      )}

      <div onClick={(e) => e.stopPropagation()}>
        <Select
          value={group.logicalOperator}
          onValueChange={(val: unknown) => {
            if (val) updateGroupOperator(group.id, val as "AND" | "OR");
          }}
        >
          <SelectTrigger className="w-26.25 text-xs font-medium bg-muted border-none">
            <SelectValue>
              {group.logicalOperator === "AND" ? "Match ALL" : "Match ANY"}
            </SelectValue>
          </SelectTrigger>
          <SelectContent
            alignItemWithTrigger={false}
            align="start"
            sideOffset={4}
          >
            <SelectItem value="AND">Match ALL</SelectItem>
            <SelectItem value="OR">Match ANY</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <span className="text-sm font-medium text-muted-foreground">
        {isRoot ? "of the following:" : "Expression Group"}
      </span>

      {!isRoot && parentId && (
        <div
          className="absolute -top-3 right-4 flex items-center bg-card border shadow-sm rounded-md px-1 py-0.5 opacity-0 group-hover/header:opacity-100 transition-all z-30 scale-95 group-hover/header:scale-100"
          onClick={(e) => e.stopPropagation()}
        >
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="ghost"
                  size="icon-lg"
                  className="h-7 w-7 text-muted-foreground hover:text-primary"
                  onClick={(e) => {
                    e.stopPropagation();
                    duplicateGroup(parentId, group.id);
                  }}
                >
                  <IconPlaceholder
                    lucide="Copy"
                    hugeicons="Copy01Icon"
                    tabler="IconCopy"
                    phosphor="Copy"
                    remixicon="RiFileCopyLine"
                    size={16}
                  />
                </Button>
              }
            />
            <TooltipContent>Duplicate Expression Group</TooltipContent>
          </Tooltip>

          <div className="w-px h-4 bg-border mx-0.5" />

          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7 text-muted-foreground hover:text-destructive"
                  onClick={(e) => {
                    e.stopPropagation();
                    removeNode(parentId, group.id);
                  }}
                >
                  <IconPlaceholder
                    lucide="Trash2"
                    hugeicons="Delete01Icon"
                    tabler="IconTrash"
                    phosphor="Trash"
                    remixicon="RiDeleteBinLine"
                    size={16}
                  />
                </Button>
              }
            />
            <TooltipContent>Delete Expression Group</TooltipContent>
          </Tooltip>
        </div>
      )}
    </div>
  );

  const mainContent =
    group.children.length === 0 ? (
      <Empty className={isRoot ? "h-full min-h-75" : "h-auto py-8"}>
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <IconPlaceholder
              lucide="Layers"
              hugeicons="Layers01Icon"
              tabler="IconLayersIntersect"
              phosphor="Stack"
              remixicon="RiStackLine"
            />
          </EmptyMedia>
          <EmptyTitle>No rules added</EmptyTitle>
          <EmptyDescription>
            Click the buttons below to add rules
          </EmptyDescription>
        </EmptyHeader>
      </Empty>
    ) : (
      <SortableContext
        id={group.id}
        items={group.children.map((c) => c.id)}
        strategy={verticalListSortingStrategy}
      >
        <div className="flex flex-col gap-3">
          {group.children.map((child) => (
            <SortableItem key={child.id} id={child.id}>
              {child.type === "group" ? (
                <ExpressionGroupItem
                  group={child}
                  parentId={group.id}
                  store={store}
                />
              ) : (
                <ExpressionRuleItem
                  rule={child}
                  parentId={group.id}
                  store={store}
                />
              )}
            </SortableItem>
          ))}
        </div>
      </SortableContext>
    );

  const footerActions = (
    <div className="flex items-center gap-2">
      <Button
        variant="outline"
        size="sm"
        className="h-8 text-xs"
        onClick={() => addRule(group.id)}
      >
        <span className="mr-1 flex items-center justify-center">
          <IconPlaceholder
            lucide="Plus"
            hugeicons="PlusSignIcon"
            tabler="IconPlus"
            phosphor="Plus"
            remixicon="RiAddLine"
            size={14}
          />
        </span>
        Add Rule
      </Button>
      <Button
        variant="outline"
        size="sm"
        className="h-8 text-xs"
        onClick={() => addGroup(group.id)}
      >
        <span className="mr-1 flex items-center justify-center">
          <IconPlaceholder
            lucide="FolderPlus"
            hugeicons="FolderAddIcon"
            tabler="IconFolderPlus"
            phosphor="FolderPlus"
            remixicon="RiFolderAddLine"
            size={14}
          />
        </span>
        Add Group
      </Button>
    </div>
  );

  if (isRoot) {
    return (
      <div className="flex flex-col flex-1 min-h-0 h-full">
        <div className="shrink-0 px-6 pt-0 pb-0">{headerContent}</div>
        <ScrollArea className="flex-1 h-full min-h-0">
          <div className="px-6 pt-4 pb-2">{mainContent}</div>
        </ScrollArea>
        <div className="shrink-0 px-6 pt-2 pb-0">{footerActions}</div>
      </div>
    );
  }

  return (
    <div className="overflow-visible w-full">
      <Card
        size="sm"
        className="gap-0 py-0 data-[size=sm]:py-0 ring-1 ring-border shadow-sm border-none bg-card overflow-visible"
      >
        <Collapsible open={isOpen} onOpenChange={setIsOpen} className="w-full">
          <CollapsibleTrigger
            nativeButton={false}
            render={headerContent}
            className="w-full"
          />
          <CollapsibleContent>
            <CardContent className="pt-2 pb-0">{mainContent}</CardContent>
            <CardFooter className="bg-transparent border-none px-4 py-2">
              {footerActions}
            </CardFooter>
          </CollapsibleContent>
        </Collapsible>
      </Card>
    </div>
  );
}

"use client";

import type { StoreApi } from "zustand";
import {
  type ExpressionRule,
  type ExpressionOperator,
  EXPRESSION_OPERATORS,
  getFieldTypeCategory,
  getOperatorsForFieldType,
} from "@buildnbuzz/form-builder-core";
import {
  useAvailableFields,
  type ExpressionStoreState,
} from "@buildnbuzz/form-builder-react";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { IconPlaceholder } from "@/components/icon-placeholder";

interface ExpressionRuleItemProps {
  rule: ExpressionRule;
  parentId: string;
  store: StoreApi<ExpressionStoreState>;
}

export function ExpressionRuleItem({
  rule,
  parentId,
  store,
}: ExpressionRuleItemProps) {
  const availableFields = useAvailableFields();

  const selectedField = availableFields.find((f) => f.id === rule.fieldId);
  const fieldCategory = getFieldTypeCategory(selectedField?.type);
  const applicableOperators = getOperatorsForFieldType(selectedField?.type);

  const selectedOperator = EXPRESSION_OPERATORS.find(
    (op) => op.value === rule.operator,
  );
  const requiresValue = selectedOperator?.requiresValue ?? true;

  const selectedValueField = availableFields.find((f) => f.id === rule.value);

  const { updateRule, removeNode, duplicateRule } = store.getState();

  const handleFieldChange = (newFieldId: string) => {
    const newField = availableFields.find((f) => f.id === newFieldId);
    const newCategory = getFieldTypeCategory(newField?.type);
    const newOps = getOperatorsForFieldType(newField?.type);

    // Reset operator if not applicable to new field type
    const currentOpApplicable = newOps.some((op) => op.value === rule.operator);
    const newOperator = currentOpApplicable ? rule.operator : "equals";

    // Reset value for type changes
    let newValue = rule.value;
    if (newCategory === "boolean") {
      newValue = "true";
    } else if (newCategory !== fieldCategory) {
      newValue = "";
    }

    updateRule(parentId, rule.id, {
      fieldId: newFieldId,
      operator: newOperator,
      value: newValue,
      valueType: newCategory === "boolean" ? "custom" : rule.valueType,
    });
  };

  // Render value input based on field type category
  const renderValueInput = () => {
    if (!requiresValue) return null;

    // Field reference mode
    if (rule.valueType !== "custom") {
      return (
        <div className="flex items-center gap-2 w-full sm:flex-1">
          <Tooltip>
            <TooltipTrigger
              render={
                <Button
                  variant="outline"
                  size="icon-lg"
                  className="shrink-0 text-muted-foreground"
                  onClick={() =>
                    updateRule(parentId, rule.id, {
                      valueType: "custom",
                      value: selectedField?.options?.[0]?.value ?? "",
                    })
                  }
                >
                  <IconPlaceholder
                    lucide="Link"
                    hugeicons="LinkSquare02Icon"
                    tabler="IconLink"
                    phosphor="Link"
                    remixicon="RiLinksLine"
                    size={16}
                  />
                </Button>
              }
            />
            <TooltipContent>Use Custom Value</TooltipContent>
          </Tooltip>
          <Select
            value={rule.value}
            onValueChange={(val: unknown) => {
              if (val)
                updateRule(parentId, rule.id, {
                  value: val as string,
                });
            }}
          >
            <SelectTrigger className="w-full h-9!">
              <SelectValue>{selectedValueField?.label}</SelectValue>
            </SelectTrigger>
            <SelectContent
              alignItemWithTrigger={false}
              align="start"
              sideOffset={4}
            >
              {availableFields
                .filter((f) => f.id !== rule.fieldId)
                .map((field) => (
                  <SelectItem key={field.id} value={field.id}>
                    {field.label}
                  </SelectItem>
                ))}
            </SelectContent>
          </Select>
        </div>
      );
    }

    const fieldRefButton = (
      <Tooltip>
        <TooltipTrigger
          render={
            <Button
              variant="outline"
              size="icon-lg"
              className="shrink-0 text-muted-foreground"
              onClick={() =>
                updateRule(parentId, rule.id, {
                  valueType: "field",
                  value: "",
                })
              }
            >
              <IconPlaceholder
                lucide="Type"
                hugeicons="TextIcon"
                tabler="IconLetterCase"
                phosphor="TextT"
                remixicon="RiText"
                size={16}
              />
            </Button>
          }
        />
        <TooltipContent>Use Field Reference</TooltipContent>
      </Tooltip>
    );

    // Fields with options (boolean, select, radio, checkbox-group): render Select dropdown
    if (selectedField?.options && selectedField.options.length > 0) {
      const matchedOption = selectedField.options.find(
        (o) => o.value === rule.value,
      );
      return (
        <div className="flex items-center gap-2 w-full sm:flex-1">
          {fieldRefButton}
          <Select
            value={rule.value}
            onValueChange={(val: unknown) => {
              if (val) updateRule(parentId, rule.id, { value: val as string });
            }}
          >
            <SelectTrigger className="w-full h-9!">
              <SelectValue>{matchedOption?.label ?? rule.value}</SelectValue>
            </SelectTrigger>
            <SelectContent
              alignItemWithTrigger={false}
              align="start"
              sideOffset={4}
            >
              {selectedField.options.map((opt) => (
                <SelectItem key={opt.value} value={opt.value}>
                  {opt.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      );
    }

    // Number fields: render number input
    if (fieldCategory === "number") {
      return (
        <div className="flex items-center gap-2 w-full sm:flex-1">
          {fieldRefButton}
          <Input
            type="number"
            placeholder="Enter number..."
            className="h-9 w-full"
            value={rule.value}
            onChange={(e) =>
              updateRule(parentId, rule.id, { value: e.target.value })
            }
          />
        </div>
      );
    }

    // Default: text input
    return (
      <div className="flex items-center gap-2 w-full sm:flex-1">
        {fieldRefButton}
        <Input
          placeholder="Enter value..."
          className="h-9 w-full"
          value={rule.value}
          onChange={(e) =>
            updateRule(parentId, rule.id, { value: e.target.value })
          }
        />
      </div>
    );
  };

  return (
    <div className="flex flex-col sm:flex-row items-start sm:items-center gap-2 bg-card p-2 rounded-lg border shadow-sm transition-all group/rule w-full relative">
      <Select
        value={rule.fieldId}
        onValueChange={(val: unknown) => {
          if (val) handleFieldChange(val as string);
        }}
      >
        <SelectTrigger className="w-full sm:w-50 h-9!">
          <SelectValue>{selectedField?.label}</SelectValue>
        </SelectTrigger>
        <SelectContent
          alignItemWithTrigger={false}
          align="start"
          sideOffset={4}
        >
          {availableFields.map((field) => (
            <SelectItem key={field.id} value={field.id}>
              {field.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      <Select
        value={rule.operator}
        onValueChange={(val: unknown) => {
          if (val)
            updateRule(parentId, rule.id, {
              operator: val as ExpressionOperator,
            });
        }}
      >
        <SelectTrigger className="w-full sm:w-40 h-9!">
          <SelectValue>{selectedOperator?.label}</SelectValue>
        </SelectTrigger>
        <SelectContent
          alignItemWithTrigger={false}
          align="start"
          sideOffset={4}
        >
          {applicableOperators.map((op) => (
            <SelectItem key={op.value} value={op.value}>
              {op.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      {renderValueInput()}

      <div className="absolute -top-3 right-4 flex items-center bg-card border shadow-sm rounded-md px-1 py-0.5 opacity-0 group-hover/rule:opacity-100 transition-all z-50 scale-95 group-hover/rule:scale-100">
        <Tooltip>
          <TooltipTrigger
            render={
              <Button
                variant="ghost"
                size="icon-lg"
                className="text-muted-foreground hover:text-primary h-7 w-7"
                onClick={() => duplicateRule(parentId, rule.id)}
              >
                <IconPlaceholder
                  lucide="Copy"
                  hugeicons="Copy01Icon"
                  tabler="IconCopy"
                  phosphor="Copy"
                  remixicon="RiFileCopyLine"
                  size={16}
                />
              </Button>
            }
          />
          <TooltipContent>Duplicate Rule</TooltipContent>
        </Tooltip>

        <div className="w-px h-4 bg-border mx-0.5" />

        <Tooltip>
          <TooltipTrigger
            render={
              <Button
                variant="ghost"
                size="icon"
                className="text-muted-foreground hover:text-destructive h-7 w-7"
                onClick={() => removeNode(parentId, rule.id)}
              >
                <IconPlaceholder
                  lucide="Trash2"
                  hugeicons="Delete01Icon"
                  tabler="IconTrash"
                  phosphor="Trash"
                  remixicon="RiDeleteBinLine"
                  size={16}
                />
              </Button>
            }
          />
          <TooltipContent>Delete Rule</TooltipContent>
        </Tooltip>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { DndContext, closestCorners } from "@dnd-kit/core";
import {
  Dialog,
  DialogContent,
