// Inline SubmitToastContent
function SubmitToastContent({ data }: { data: Record<string, unknown> }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(JSON.stringify(data, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="relative mt-2 w-full">
      <Button
        variant="ghost"
        size="icon"
        onClick={handleCopy}
        className="absolute right-2 top-2 h-7 w-7"
        title="Copy JSON"
      >
        {copied ? (
          <IconPlaceholder
            lucide="Check"
            hugeicons="Tick01Icon"
            tabler="IconCheck"
            phosphor="Check"
            remixicon="RiCheckLine"
            size={14}
            className="text-primary"
          />
        ) : (
          <IconPlaceholder
            lucide="Copy"
            hugeicons="Copy01Icon"
            tabler="IconCopy"
            phosphor="Copy"
            remixicon="RiFileCopyLine"
            size={14}
          />
        )}
      </Button>
      <pre className="max-h-75 overflow-auto rounded-md bg-muted p-3 pt-6 text-xs text-muted-foreground sm:p-3 sm:pr-10 sm:pt-3">
        <code>{JSON.stringify(data, null, 2)}</code>
      </pre>
    </div>
  );
}

