interface WindowFrameProps {
  children: React.ReactNode;
  className?: string;
}

export function WindowFrame({ children, className }: WindowFrameProps) {
  const viewport = useBuilderStore((state) => state.viewport);
  const zoom = useBuilderStore((state) => state.zoom);
  const mode = useBuilderStore((state) => state.mode);

  const getViewportWidth = () => {
    switch (viewport) {
      case "mobile":
        return "375px";
      case "tablet":
        return "768px";
      default:
        return "100%";
    }
  };

  return (
    <div
      className={cn(
        "bg-background h-160 border border-border rounded-xl shadow-[0_0_60px_-5px_hsl(var(--primary)/0.4)] flex flex-col relative transition-all duration-300 ease-in-out origin-top overflow-hidden",
        className,
      )}
      style={{
        transform: `scale(${zoom})`,
        width: getViewportWidth(),
        maxWidth: viewport === "desktop" ? "896px" : getViewportWidth(),
      }}
    >
      <div className="h-10 bg-muted/50 border-b flex items-center px-4 justify-between shrink-0">
        <div className="flex items-center gap-1.5 w-20">
          <div className="w-3 h-3 rounded-full bg-destructive/80" />
          <div className="w-3 h-3 rounded-full bg-yellow-500/80" />
          <div className="w-3 h-3 rounded-full bg-green-500/80" />
        </div>
        <div className="text-xs text-muted-foreground font-medium flex-1 text-center">
          {mode === "preview" ? "Preview Mode" : "Edit Mode"}
        </div>
        <div className="w-20" />
      </div>

      {/* Content Area */}
      <ScrollArea className="flex-1 overflow-hidden">{children}</ScrollArea>
    </div>
  );
}

import { PreviewForm } from "./preview/preview-form";

/**
 * Centered frame for the canvas to simulate different viewports.
 */
const CanvasFrame = () => {
  const rootIds = useBuilderStore((s) => s.rootIds);
  const mode = useBuilderStore((s) => s.mode);
  const selectNode = useBuilderStore((s) => s.selectNode);

  const isPreviewMode = mode === "preview";

  const { setNodeRef } = useDroppable({
    id: "root",
    disabled: isPreviewMode,
  });

  const handleBackgroundClick = () => {
    if (!isPreviewMode) {
      selectNode(null);
    }
  };

  return (
    <div
      className="p-8 pt-10 flex justify-center items-start min-h-full"
      onClick={handleBackgroundClick}
    >
      <WindowFrame>
        <div
          ref={isPreviewMode ? undefined : setNodeRef}
          className="p-8 max-w-2xl mx-auto min-h-full relative"
          data-id="root"
        >
          {rootIds.length === 0 ? (
            <EmptyCanvas />
          ) : isPreviewMode ? (
            <PreviewForm />
          ) : (
            <div className="min-h-120 relative">
              <SortableContext
                items={rootIds}
                strategy={verticalListSortingStrategy}
              >
                <HeadlessCanvas
                  nodeRenderer={({ node, content }) => (
                    <NodeWrapper node={node}>{content}</NodeWrapper>
                  )}
                />
              </SortableContext>
            </div>
          )}
        </div>
      </WindowFrame>
    </div>
  );
};

/**
 * Main Form Builder component that orchestrates the entire UI.
 */
const NEW_BUILDER_STORAGE_NAMESPACE = "buzzform-builder:v2:forms";

export const FormBuilder = () => {
  const storageProvider = React.useMemo(() => {
    if (typeof window === "undefined") return null;
    try {
      return getBrowserLocalStorageProvider(NEW_BUILDER_STORAGE_NAMESPACE);
    } catch {
      return null;
    }
  }, []);

  return (
    <DefaultBuilderProvider
      registry={SHADCN_BUILDER_REGISTRY}
      storageProvider={storageProvider}
    >
      <FormBuilderContent storageProvider={storageProvider} />
    </DefaultBuilderProvider>
  );
};

/**
 * Inner component that uses builder hooks.
 */
const FormBuilderContent = ({
  storageProvider,
}: {
  storageProvider: BuilderStorageProvider | null;
}) => {
  const mounted = React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false,
  );
  const containerRef = useRef<HTMLDivElement>(null);
  const zoom = useBuilderStore((state) => state.zoom);
  const setZoom = useBuilderStore((state) => state.setZoom);
  const mode = useBuilderStore((s) => s.mode);

  const onSubmit = async (data: Record<string, unknown>) => {
    await new Promise((r) => setTimeout(r, 500));
    toast("Form Submitted!", {
      description: <SubmitToastContent data={data} />,
      duration: 10000,
    });
  };

  // Handle Ctrl+Wheel zoom
  useEffect(() => {
    if (!mounted) return;
    const container = containerRef.current;
    if (!container) return;

    const handleWheel = (e: WheelEvent) => {
      if (e.ctrlKey) {
        e.preventDefault();
        const delta = e.deltaY * -0.002;
        const nextZoom = Math.round((zoom + delta) * 100) / 100;
        // Clamp zoom between 0.25 and 2
        const clampedZoom = Math.max(0.25, Math.min(2, nextZoom));
        setZoom(clampedZoom);
      }
    };

    container.addEventListener("wheel", handleWheel, { passive: false });
    return () => container.removeEventListener("wheel", handleWheel);
  }, [zoom, setZoom, mounted]);

  if (!mounted) return null;

  return (
    <BuilderDndProvider
      renderOverlay={({ activeId, activeData }) => (
        <DragOverlayItem activeId={activeId} activeData={activeData} />
      )}
    >
      <BuilderFormProvider mode={mode} onSubmit={onSubmit}>
        <MobileOverlay />
        <div className="flex flex-col h-screen w-full bg-muted/30 overflow-hidden text-foreground">
          {/* Top Header */}
          <SiteHeader storageProvider={storageProvider} />

          {/* Main Layout */}
          <SidebarProvider className="flex-1 overflow-hidden min-h-0 min-w-0">
            <div className="flex h-full w-full">
              {/* Left Sidebar: Components */}
              <div
                className={cn(
                  "border-r bg-background transition-all duration-300 ease-in-out",
                  mode === "preview"
                    ? "w-0 opacity-0 overflow-hidden border-none"
                    : "w-64",
                )}
              >
                <div className="w-64">
                  <FieldSidebar />
                </div>
              </div>

              {/* Central Canvas */}
              <main className="flex-1 flex flex-col relative overflow-hidden bg-muted/20 min-w-0">
                <CanvasToolbar />
                <div ref={containerRef} className="flex-1 min-h-0">
                  <div className="h-full overflow-auto [&::-webkit-scrollbar]:hidden [scrollbar-width:none] bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] dark:bg-[radial-gradient(#1f2937_1px,transparent_1px)] bg-size-[20px_20px]">
                    <CanvasFrame />
                  </div>
                </div>
              </main>

              {/* Right Sidebar: Properties */}
              <aside
                className={cn(
                  "border-l bg-background flex flex-col shrink-0 transition-all duration-300 ease-in-out",
                  mode === "preview"
                    ? "w-0 opacity-0 overflow-hidden border-none"
                    : "w-80",
                )}
              >
                <div className="w-80 h-full flex flex-col">
                  <PropertyPanel />
                </div>
              </aside>
            </div>
          </SidebarProvider>
        </div>
      </BuilderFormProvider>
    </BuilderDndProvider>
  );
};

