import { flattenFieldToFormValues } from "@buildnbuzz/form-builder-core";
import type { Field, FormSchema } from "@buildnbuzz/form-core";
import { ExpressionCheckbox } from "./expression-builder/expression-checkbox";
import { registry as shadcnRegistry } from "../registry";

/** Renders nothing — syncs form state ↔ builder store bidirectionally. */
function SyncPropertyState({
  update,
  data,
  schema,
}: {
  update: (data: Record<string, unknown>) => void;
  data: Record<string, unknown>;
  schema: Field[];
}) {
  const { form } = useFormContext();
  useSyncProperty({ form, data, schema, update });
  return null;
}

/**
 * Side panel for editing node or global form properties.
 */
export const PropertyPanel = () => {
  const { registry } = useBuilderContext();

  return (
    <div className="flex h-full flex-col bg-background border-l overflow-hidden">
      <BuilderProperties
        render={({ node, id, schema, data, update }) => {
          const entry = node
            ? getRegistryEntry(registry, node.field.type)
            : null;
          const label =
            entry?.sidebar.label ??
            (id === "form" ? "Form Settings" : "Properties");

          const defaultValues = flattenFieldToFormValues(
            data as unknown as Field,
            schema,
          );

          return (
            <>
              <div className="p-4 border-b h-header flex items-center">
                {node && entry ? (
                  <div className="flex items-center gap-3 w-full">
                    <div className="flex h-10 w-10 items-center justify-center rounded-xl border bg-secondary/30 shadow-sm">
                      {node && (
                        <FieldIcon
                          type={node.field.type}
                          size={20}
                          className="text-foreground"
                        />
                      )}
                    </div>
                    <div className="flex flex-col gap-0.5 min-w-0 flex-1">
                      <span className="font-semibold text-sm truncate">
                        {label}
                      </span>
                      <span className="text-[11px] text-muted-foreground/80 truncate">
                        Properties
                      </span>
                    </div>
                  </div>
                ) : (
                  <div className="flex items-center gap-3 w-full">
                    <div className="flex h-10 w-10 items-center justify-center rounded-xl border bg-secondary/30 shadow-sm">
                      <IconPlaceholder
                        lucide="Settings"
                        hugeicons="Settings01Icon"
                        size={20}
                        className="text-muted-foreground"
                      />
                    </div>
                    <div className="flex flex-col gap-0.5 min-w-0 flex-1">
                      <span className="font-semibold text-sm">
                        Form Settings
                      </span>
                      <span className="text-[11px] text-muted-foreground/80 truncate">
                        Configuration
                      </span>
                    </div>
                  </div>
                )}
              </div>
              <div className="flex-1 min-h-0">
                <ScrollArea className="h-full">
                  <div className="flex flex-col gap-6 p-4">
                    {schema.length > 0 ? (
                      <Form
                        key={id}
                        schema={{ fields: schema } as unknown as FormSchema}
                        defaultValues={defaultValues}
                        registries={{
                          fields: {
                            ...shadcnRegistry,
                            checkbox: ExpressionCheckbox,
                            switch: ExpressionCheckbox,
                          },
                        }}
                      >
                        <FormContent autoRender as="div" className="gap-6">
                          <SyncPropertyState
                            update={update}
                            data={data}
                            schema={schema}
                          />
                        </FormContent>
                      </Form>
                    ) : (
                      <div className="flex flex-col items-center justify-center gap-2 py-10 text-center opacity-30">
                        <span className="text-[11px]">
                          No properties available
                        </span>
                      </div>
                    )}
                  </div>
                </ScrollArea>
              </div>
            </>
          );
        }}
      />
    </div>
  );
};

"use client";

import React from "react";
import {
  DEFAULT_FIELD_REGISTRY,
  isDataField,
} from "@buildnbuzz/form-builder-core";
import { Field, type DataField } from "@buildnbuzz/form-react";
import { registry as shadcnRegistry } from "../registry";
import { RowRenderer } from "./layout/row-renderer";
import { GroupRenderer } from "./layout/group-renderer";
import { ArrayRenderer } from "./layout/array-renderer";
import { TabsRenderer } from "./layout/tabs-renderer";
import { CollapsibleRenderer } from "./layout/collapsible-renderer";
import {
  useBuilderFormContext,
  type BuilderNodeRendererProps,
  type BuilderFieldRegistry,
} from "@buildnbuzz/form-builder-react";

/**
 * Generic renderer for data fields that uses the runtime components.
 * Wraps the component in a Field to provide the necessary headless context.
 */
const DataFieldRenderer = ({ field }: BuilderNodeRendererProps) => {
  const { form } = useBuilderFormContext();
  const Component = shadcnRegistry[field.type];

  if (!Component || !isDataField(field)) {
    return null;
  }

  return (
    <Field field={field as DataField} form={form}>
      <Component />
    </Field>
  );
};

const specializedRenderers: Record<
  string,
  React.ComponentType<BuilderNodeRendererProps>
> = {
  row: RowRenderer,
  group: GroupRenderer,
  array: ArrayRenderer,
  tabs: TabsRenderer,
  collapsible: CollapsibleRenderer,
};

/**
 * Shadcn-specific builder registry.
 * Hydrates the core metadata registry with React renderers.
 */
export const SHADCN_BUILDER_REGISTRY: BuilderFieldRegistry = Object.entries(
  DEFAULT_FIELD_REGISTRY,
).reduce((acc, [type, entry]) => {
  if (!entry) return acc;

  acc[type] = {
    ...entry,
    renderer: (specializedRenderers[type] ??
      DataFieldRenderer) as React.ComponentType<BuilderNodeRendererProps>,
  };
  return acc;
}, {} as BuilderFieldRegistry);
